import { DocumentSignal, type DocumentInfo } from "./solution";

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

function equal(actual: unknown, expected: unknown, message: string): void {
  if (actual !== expected) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}

function documentEqual(actual: DocumentInfo, title: string, tags: string[], message: string): void {
  equal(actual.title, title, `${message} title`);
  equal(actual.tags.length, tags.length, `${message} tag count`);
  for (let i = 0; i < tags.length; i += 1) equal(actual.tags[i], tags[i], `${message} tag ${i}`);
}

function throwsType(fn: () => unknown, message: string): void {
  try {
    fn();
  } catch (error) {
    assert(error instanceof TypeError, message);
    return;
  }
  throw new Error(`${message}: did not throw`);
}

const initial: DocumentInfo = { title: "  Plan  ", tags: [" alpha ", "", "alpha"] };
const signal = new DocumentSignal(initial);
initial.title = "changed";
initial.tags[0] = "changed";
initial.tags.push("extra");
documentEqual(signal.value, "Plan", ["alpha", "", "alpha"], "constructor trims and detaches input");

const firstRead = signal.value;
const secondRead = signal.value;
assert(firstRead !== secondRead, "getter returns a fresh document");
assert(firstRead.tags !== secondRead.tags, "getter returns a fresh tags array");
firstRead.title = "mutated";
firstRead.tags[0] = "mutated";
documentEqual(signal.value, "Plan", ["alpha", "", "alpha"], "getter does not expose state");

const events: string[] = [];
let unsubscribeSecond = () => {};
const unsubscribeFirst = signal.subscribe((value) => {
  events.push(`first:${value.title}:${value.tags.join("|")}`);
  value.title = "listener mutation";
  value.tags[0] = "listener mutation";
  unsubscribeSecond();
});
unsubscribeSecond = signal.subscribe((value) => {
  events.push(`second:${value.title}:${value.tags.join("|")}`);
});

equal(events.length, 0, "subscribe does not immediately notify");
const replacement: DocumentInfo = { title: "  Next  ", tags: [" one ", " ", "one"] };
signal.replace(replacement);
equal(events.length, 2, "snapshot includes listener unsubscribed during notification");
equal(events[0], "first:Next:one||one", "notifies first listener first");
equal(events[1], "second:Next:one||one", "each listener receives an independent copy");
replacement.title = "outside";
replacement.tags[0] = "outside";
documentEqual(signal.value, "Next", ["one", "", "one"], "replace detaches caller input and listener copies");

signal.replace({ title: "Third", tags: [] });
equal(events.length, 3, "unsubscribed listener is absent from later snapshot");
equal(events[2], "first:Third:", "remaining listener is notified");
unsubscribeFirst();
unsubscribeFirst();
signal.replace({ title: "Fourth", tags: [] });
equal(events.length, 3, "unsubscribe is idempotent");

let notifications = 0;
signal.subscribe(() => { notifications += 1; });
throwsType(() => signal.replace({ title: "   ", tags: ["x"] }), "rejects empty trimmed title");
throwsType(() => signal.replace({ title: "Valid", tags: [1 as unknown as string] }), "rejects non-string tag");
equal(notifications, 0, "invalid replacements do not notify");
documentEqual(signal.value, "Fourth", [], "invalid replacements preserve state");

throwsType(() => new DocumentSignal({ title: 4 as unknown as string, tags: [] }), "constructor rejects non-string title");
throwsType(() => new DocumentSignal({ title: "Valid", tags: null as unknown as string[] }), "constructor rejects non-array tags");
throwsType(() => signal.subscribe(null as unknown as (value: DocumentInfo) => void), "subscribe rejects non-function");

